Contract ProcessSaleService::makeNewSale(): Boolean {

            precondition:
          CashDesk.allInstances()->exists(cd: CashDesk|cd = self.CurrentCashDesk) and self.CurrentCashDesk.IsOpened = true and (self.CurrentSale.oclIsUndefined() = true or self.CurrentSale.IsComplete = true)

            postcondition:
          result = true and self.CurrentSale.oclIsNew() = true and self.CurrentSale.IsComplete = false and self.CurrentSale.IsReadytoPay = false and self.CurrentSale.BelongedCashDesk = self.CurrentCashDesk and self.CurrentCashDesk.ContainedSales->exists(s: Sale|s = self.CurrentSale)

        }
